import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose2d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
__device__ __forceinline__ int floordiv_i(int a, int b) {
    int q = a / b;
    int r = a % b;
    if (r != 0 && ((r < 0) != (b < 0))) q -= 1;
    return q;
}
template <typename T>
__global__ void __launch_bounds__(256, 4) conv_transpose2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups,
    int OH, int OW,
    int IH_TILE, int IW_TILE)
{
    constexpr int Threads    = 256;
    constexpr int OcPerBlock = 2;
    constexpr int TILE_OH    = 4;
    constexpr int TILE_OW    = 64;
    const int Cin_pg  = Cin / groups;
    const int Cout_pg = Cout / groups;
    const int tid = threadIdx.x;
    const int oh_local0 = tid / TILE_OW;
    const int ow_local0 = tid % TILE_OW;
    const int n = blockIdx.z;
    const int n_oh_tiles = (OH + TILE_OH - 1) / TILE_OH;
    const int ow_tile = blockIdx.x;
    const int combined = blockIdx.y;
    const int oh_tile = combined % n_oh_tiles;
    const int oc_tile = combined / n_oh_tiles;
    const int c_base  = oc_tile * OcPerBlock;
    const int oh0 = oh_tile * TILE_OH;
    const int ow0 = ow_tile * TILE_OW;
    const int oh = oh0 + oh_local0;
    const int ow = ow0 + ow_local0;
    const bool valid_out = (oh < OH) && (ow < OW);
    // Strides for X (N,Cin,H,Win) contiguous
    const int64_t sXn = (int64_t)Cin * H * Win;
    const int64_t sXc = (int64_t)H * Win;
    const int64_t sXh = (int64_t)Win;
    // Strides for Y (N,Cout,OH,OW) contiguous
    const int64_t sYn = (int64_t)Cout * OH * OW;
    const int64_t sYc = (int64_t)OH * OW;
    const int64_t sYh = (int64_t)OW;
    // Weight (Cin, Cout_pg, KH, KW) contiguous
    const int64_t sWc  = (int64_t)Cout_pg * KH * KW;
    const int64_t sWoc = (int64_t)KH * KW;
    const int64_t sWkh = (int64_t)KW;
    auto mX = make_tensor(
        make_gmem_ptr(X + (int64_t)n * sXn),
        make_shape(Cin, H, Win),
        make_stride(sXc, sXh, Int<1>{})
    );
    auto mY = make_tensor(
        make_gmem_ptr(Y + (int64_t)n * sYn),
        make_shape(Cout, OH, OW),
        make_stride(sYc, sYh, Int<1>{})
    );
    auto mW = make_tensor(
        make_gmem_ptr(W),
        make_shape(Cin, Cout_pg, KH, KW),
        make_stride(sWc, sWoc, sWkh, Int<1>{})
    );
    extern __shared__ unsigned char smem_raw[];
    T* sW_ptr = reinterpret_cast<T*>(smem_raw);
    size_t w_elems = (size_t)OcPerBlock * (size_t)Cin_pg * (size_t)KH * (size_t)KW;
    T* sX_ptr = sW_ptr + w_elems;
    // sW shape: (OcPerBlock, Cin_pg, KH, KW)
    auto sW = make_tensor(
        make_smem_ptr(sW_ptr),
        make_shape(Int<OcPerBlock>{}, Cin_pg, KH, KW),
        make_stride(Cin_pg * KH * KW, KH * KW, KW, Int<1>{})
    );
    // Load weight tile into shared memory
    int total_w = OcPerBlock * Cin_pg * KH * KW;
    for (int idx = tid; idx < total_w; idx += Threads) {
        int tmp = idx;
        int kw  = tmp % KW;  tmp /= KW;
        int kh  = tmp % KH;  tmp /= KH;
        int icl = tmp % Cin_pg; tmp /= Cin_pg;
        int cc  = tmp;
        int oc = c_base + cc;
        T wval = T(0);
        if (oc < Cout) {
            int g = oc / Cout_pg;
            int oc_local = oc % Cout_pg;
            int ic_full = g * Cin_pg + icl;
            wval = mW(ic_full, oc_local, kh, kw);
        }
        sW(cc, icl, kh, kw) = wval;
    }
    // Determine group span covered by this oc tile (usually 1 group, at most OcPerBlock)
    int g0 = c_base / Cout_pg;
    int oc_last = c_base + OcPerBlock - 1;
    if (oc_last >= Cout) oc_last = Cout - 1;
    int g1 = oc_last / Cout_pg;
    int num_groups = g1 - g0 + 1;
    int ic_start = g0 * Cin_pg;
    int ic_count = num_groups * Cin_pg;
    // Compute input tile bounds (safe upper-bound halo, shared across the whole CTA)
    int th_min = oh0 + pad_h - (KH - 1) * dil_h;
    int tw_min = ow0 + pad_w - (KW - 1) * dil_w;
    int ih_lo = floordiv_i(th_min, stride_h);
    int iw_lo = floordiv_i(tw_min, stride_w);
    auto sX = make_tensor(
        make_smem_ptr(sX_ptr),
        make_shape(ic_count, IH_TILE, IW_TILE),
        make_stride(IH_TILE * IW_TILE, IW_TILE, Int<1>{})
    );
    // Cooperative staging of the reusable input tile into shared memory
    int total_x = ic_count * IH_TILE * IW_TILE;
    for (int idx = tid; idx < total_x; idx += Threads) {
        int tmp = idx;
        int iwl = tmp % IW_TILE; tmp /= IW_TILE;
        int ihl = tmp % IH_TILE; tmp /= IH_TILE;
        int icl = tmp;
        int ih = ih_lo + ihl;
        int iw = iw_lo + iwl;
        T xval = T(0);
        if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
            int ic_full = ic_start + icl;
            xval = mX(ic_full, ih, iw);
        }
        sX(icl, ihl, iwl) = xval;
    }
    __syncthreads();
    float acc[OcPerBlock];
    #pragma unroll
    for (int cc = 0; cc < OcPerBlock; ++cc) {
        int oc = c_base + cc;
        float bval = 0.0f;
        if (B != nullptr && oc < Cout) {
            bval = (float)B[oc];
        }
        acc[cc] = bval;
    }
    if (valid_out) {
        for (int kh = 0; kh < KH; ++kh) {
            int th = oh + pad_h - kh * dil_h;
            int rem_h = th % stride_h;
            if (rem_h != 0) continue;
            int ih = th / stride_h;
            if (ih < 0 || ih >= H) continue;
            int ihl = ih - ih_lo;
            for (int kw = 0; kw < KW; ++kw) {
                int tw = ow + pad_w - kw * dil_w;
                int rem_w = tw % stride_w;
                if (rem_w != 0) continue;
                int iw = tw / stride_w;
                if (iw < 0 || iw >= Win) continue;
                int iwl = iw - iw_lo;
                if (num_groups == 1) {
                    float local_acc[OcPerBlock];
                    #pragma unroll
                    for (int cc = 0; cc < OcPerBlock; ++cc) local_acc[cc] = 0.0f;
                    for (int icl = 0; icl < Cin_pg; ++icl) {
                        float xval = (float)sX(icl, ihl, iwl);
                        #pragma unroll
                        for (int cc = 0; cc < OcPerBlock; ++cc) {
                            float wval = (float)sW(cc, icl, kh, kw);
                            local_acc[cc] += xval * wval;
                        }
                    }
                    #pragma unroll
                    for (int cc = 0; cc < OcPerBlock; ++cc) {
                        int oc = c_base + cc;
                        if (oc < Cout) acc[cc] += local_acc[cc];
                    }
                } else {
                    #pragma unroll
                    for (int cc = 0; cc < OcPerBlock; ++cc) {
                        int oc = c_base + cc;
                        if (oc >= Cout) continue;
                        int g = oc / Cout_pg;
                        int icl_off = (g - g0) * Cin_pg;
                        float local_acc = 0.0f;
                        for (int icl = 0; icl < Cin_pg; ++icl) {
                            float xval = (float)sX(icl_off + icl, ihl, iwl);
                            float wval = (float)sW(cc, icl, kh, kw);
                            local_acc += xval * wval;
                        }
                        acc[cc] += local_acc;
                    }
                }
            }
        }
    }
    if (valid_out) {
        #pragma unroll
        for (int cc = 0; cc < OcPerBlock; ++cc) {
            int oc = c_base + cc;
            if (oc >= Cout) continue;
            mY(oc, oh, ow) = static_cast<T>(acc[cc]);
        }
    }
}
torch::Tensor conv_transpose2d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(w.is_cuda(), "w must be CUDA");
    if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
    if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be [N,Cin,H,W]");
    TORCH_CHECK(w.dim() == 4, "w must be [Cin, Cout/groups, KH, KW]");
    int64_t N   = x.size(0);
    int64_t Cin = x.size(1);
    int64_t H   = x.size(2);
    int64_t Win = x.size(3);
    int64_t Cin_w   = w.size(0);
    int64_t Cout_pg = w.size(1);
    int64_t KH      = w.size(2);
    int64_t KW      = w.size(3);
    TORCH_CHECK(Cin_w == Cin, "weight in_channels mismatch");
    int64_t Cout = Cout_pg * groups;
    TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be > 0");
    TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be > 0");
    TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be >= 0");
    TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
    int64_t OH = (H - 1) * stride_h - 2 * pad_h + dil_h * (KH - 1) + 1;
    int64_t OW = (Win - 1) * stride_w - 2 * pad_w + dil_w * (KW - 1) + 1;
    TORCH_CHECK(OH > 0 && OW > 0, "invalid output size computed");
    auto x_c = x.contiguous();
    auto w_c = w.contiguous();
    torch::Tensor b_c;
    const float* b_ptr = nullptr;
    if (b.has_value()) {
        b_c = b.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
        b_ptr = b_c.data_ptr<float>();
    }
    auto y = torch::empty({N, Cout, OH, OW}, x.options());
    constexpr int Threads = 256;
    constexpr int OcPerBlock = 2;
    constexpr int TILE_OH = 4;
    constexpr int TILE_OW = 64;
    int64_t Cin_pg = Cin / groups;
    int n_oc_tiles = (int)((Cout + OcPerBlock - 1) / OcPerBlock);
    int n_oh_tiles = (int)((OH + TILE_OH - 1) / TILE_OH);
    int n_ow_tiles = (int)((OW + TILE_OW - 1) / TILE_OW);
    dim3 block(Threads);
    dim3 grid(
        (unsigned)n_ow_tiles,
        (unsigned)(n_oh_tiles * n_oc_tiles),
        (unsigned)N
    );
    int IH_TILE = ((TILE_OH - 1) + (int)(KH - 1) * dil_h) / stride_h + 2;
    int IW_TILE = ((TILE_OW - 1) + (int)(KW - 1) * dil_w) / stride_w + 2;
    if (IH_TILE < 1) IH_TILE = 1;
    if (IW_TILE < 1) IW_TILE = 1;
    int64_t ic_count_max = (groups < OcPerBlock ? (int64_t)groups : (int64_t)OcPerBlock) * Cin_pg;
    size_t w_bytes = (size_t)OcPerBlock * (size_t)Cin_pg * (size_t)KH * (size_t)KW * sizeof(float);
    size_t x_bytes = (size_t)ic_count_max * (size_t)IH_TILE * (size_t)IW_TILE * sizeof(float);
    size_t shmem_bytes = w_bytes + x_bytes;
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    conv_transpose2d_kernel<float><<<grid, block, shmem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)Cin, (int)H, (int)Win,
        (int)Cout, (int)KH, (int)KW,
        stride_h, stride_w,
        pad_h, pad_w,
        dil_h, dil_w,
        groups,
        (int)OH, (int)OW,
        IH_TILE, IW_TILE
    );
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv_transpose2d_kernel launch failed: ", cudaGetErrorString(err));
    return y;
}
"""

conv_transpose2d_ext = load_inline(
    name="cute_conv_transpose2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Grouped, dilated, padded 2D transposed convolution implemented with a
    custom CUDA kernel built using CuTe tensors.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1), padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = tuple(kernel_size)
        self.stride = tuple(stride)
        self.padding = tuple(padding)
        self.dilation = tuple(dilation)
        self.groups = int(groups)

        KH, KW = self.kernel_size
        Cout_pg = out_channels // groups

        # weight layout matches torch's ConvTranspose2d: (Cin, Cout/groups, KH, KW)
        self.weight = nn.Parameter(torch.empty(in_channels, Cout_pg, KH, KW))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv_transpose2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels // self.groups * self.kernel_size[0] * self.kernel_size[1]
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride[0]), int(self.stride[1]),
            int(self.padding[0]), int(self.padding[1]),
            int(self.dilation[0]), int(self.dilation[1]),
            int(self.groups),
        )

