import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose2d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
__device__ __forceinline__ int floordiv_i(int a, int b) {
    int q = a / b;
    int r = a % b;
    if (r != 0 && ((r < 0) != (b < 0))) q -= 1;
    return q;
}
template <typename T>
__global__ void __launch_bounds__(256, 3) conv_transpose2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups,
    int OH, int OW,
    int IH_TILE, int IW_TILE)
{
    constexpr int Threads    = 256;
    constexpr int OcPerBlock = 2;
    constexpr int TILE_OH    = 4;
    constexpr int TILE_OW    = 64;
    const int Cin_pg  = Cin / groups;
    const int Cout_pg = Cout / groups;
    const int tid = threadIdx.x;
    const int oh_local0 = tid / TILE_OW;
    const int ow_local0 = tid % TILE_OW;
    const int n = blockIdx.z;
    const int n_oh_tiles = (OH + TILE_OH - 1) / TILE_OH;
    const int ow_tile = blockIdx.x;
    const int combined = blockIdx.y;
    const int oh_tile = combined % n_oh_tiles;
    const int oc_tile = combined / n_oh_tiles;
    const int c_base  = oc_tile * OcPerBlock;
    const int oh0 = oh_tile * TILE_OH;
    const int ow0 = ow_tile * TILE_OW;
    const int oh = oh0 + oh_local0;
    const int ow = ow0 + ow_local0;
    const bool valid_out = (oh < OH) && (ow < OW);
    // Strides for X (N,Cin,H,Win) contiguous
    const int64_t sXn = (int64_t)Cin * H * Win;
    const int64_t sXc = (int64_t)H * Win;
    const int64_t sXh = (int64_t)Win;
    // Strides for Y (N,Cout,OH,OW) contiguous
    const int64_t sYn = (int64_t)Cout * OH * OW;
    const int64_t sYc = (int64_t)OH * OW;
    const int64_t sYh = (int64_t)OW;
    // Weight (Cin, Cout_pg, KH, KW) contiguous
    const int64_t sWc  = (int64_t)Cout_pg * KH * KW;
    const int64_t sWoc = (int64_t)KH * KW;
    const int64_t sWkh = (int64_t)KW;
    auto mX = make_tensor(
        make_gmem_ptr(X + (int64_t)n * sXn),
        make_shape(Cin, H, Win),
        make_stride(sXc, sXh, Int<1>{})
    );
    auto mY = make_tensor(
        make_gmem_ptr(Y + (int64_t)n * sYn),
        make_shape(Cout, OH, OW),
        make_stride(sYc, sYh, Int<1>{})
    );
    auto mW = make_tensor(
        make_gmem_ptr(W),
        make_shape(Cin, Cout_pg, KH, KW),
        make_stride(sWc, sWoc, sWkh, Int<1>{})
    );
    extern __shared__ unsigned char smem_raw[];
    T* sW_ptr = reinterpret_cast<T*>(smem_raw);
    size_t w_elems = (size_t)OcPerBlock * (size_t)Cin_pg * (size_t)KH * (size_t)KW;
    T* sX_ptr = sW_ptr + w_elems;
    // sW shape: (OcPerBlock, Cin_pg, KH, KW)
    auto sW = make_tensor(
        make_smem_ptr(sW_ptr),
        make_shape(Int<OcPerBlock>{}, Cin_pg, KH, KW),
        make_stride(Cin_pg * KH * KW, KH * KW, KW, Int<1>{})
    );
    // Load weight tile into shared memory
    int total_w = OcPerBlock * Cin_pg * KH * KW;
    for (int idx = tid; idx < total_w; idx += Threads) {
        int tmp = idx;
        int kw  = tmp % KW;  tmp /= KW;
        int kh  = tmp % KH;  tmp /= KH;
        int icl = tmp % Cin_pg; tmp /= Cin_pg;
        int cc  = tmp;
        int oc = c_base + cc;
        T wval = T(0);
        if (oc < Cout) {
            int g = oc / Cout_pg;
            int oc_local = oc % Cout_pg;
            int ic_full = g * Cin_pg + icl;
            wval = mW(ic_full, oc_local, kh, kw);
        }
        sW(cc, icl, kh, kw) = wval;
    }
    // Determine group span covered by this oc tile (usually 1 group, at most OcPerBlock)
    int g0 = c_base / Cout_pg;
    int oc_last = c_base + OcPerBlock - 1;
    if (oc_last >= Cout) oc_last = Cout - 1;
    int g1 = oc_last / Cout_pg;
    int num_groups = g1 - g0 + 1;
    int ic_start = g0 * Cin_pg;
    int ic_count = num_groups * Cin_pg;
    // Compute input tile bounds (safe upper-bound halo, shared across the whole CTA)
    int th_min = oh0 + pad_h - (KH - 1) * dil_h;
    int tw_min = ow0 + pad_w - (KW - 1) * dil_w;
    int ih_lo = floordiv_i(th_min, stride_h);
    int iw_lo = floordiv_i(tw_min, stride_w);
    auto sX = make_tensor(
        make_smem_ptr(sX_ptr),
        make_shape(ic_count, IH_TILE, IW_TILE),
        make_stride(IH_TILE * IW_TILE, IW_TILE, Int<1>{})
    );
    // Cooperative staging of the reusable input tile into shared memory
    int total_x = ic_count * IH_TILE * IW_TILE;
    for (int idx = tid; idx < total_x; idx += Threads) {
        int tmp = idx;
        int iwl = tmp % IW_TILE; tmp /= IW_TILE;
        int ihl = tmp % IH_TILE; tmp /= IH_TILE;
        int icl = tmp;
        int ih = ih_lo + ihl;
        int iw = iw_lo + iwl;
        T xval = T(0);
        if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
            int ic_full = ic_start + icl;
            xval = mX(ic_full, ih, iw);
        }
        sX(icl, ihl, iwl) = xval;
    }
    __syncthreads();
    float acc[OcPerBlock];
    #pragma unroll
    for (int cc = 0; cc < OcPerBlock; ++cc) {
        int oc = c_base + cc;
        float bval = 0.0f;
        if (B != nullptr && oc < Cout) {
