cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups,
    int OH, int OW)
{
    constexpr int Threads    = 256;
    constexpr int PVec       = 2;
    constexpr int OcPerBlock = 4;

    const int Cin_pg  = Cin / groups;
    const int Cout_pg = Cout / groups;

    const int tid = threadIdx.x;

    const int n       = blockIdx.z;
    const int oc_tile = blockIdx.y;
    const int c_base  = oc_tile * OcPerBlock;

    const int P_total = OH * OW;
    const int PTile   = Threads * PVec;
    const int p_block = blockIdx.x * PTile;

    // Strides for X (N,Cin,H,Win) contiguous
    const int64_t sXn = (int64_t)Cin * H * Win;
    const int64_t sXc = (int64_t)H * Win;
    const int64_t sXh = (int64_t)Win;

    // Strides for Y (N,Cout,OH,OW) contiguous
    const int64_t sYn = (int64_t)Cout * OH * OW;
    const int64_t sYc = (int64_t)OH * OW;
    const int64_t sYh = (int64_t)OW;

    // Weight (Cin, Cout_pg, KH, KW) contiguous
    const int64_t sWc  = (int64_t)Cout_pg * KH * KW;
    const int64_t sWoc = (int64_t)KH * KW;
    const int64_t sWkh = (int64_t)KW;

    auto mX = make_tensor(
        make_gmem_ptr(X + (int64_t)n * sXn),
        make_shape(Cin, H, Win),
        make_stride(sXc, sXh, Int<1>{})
    );

    auto mY = make_tensor(
        make_gmem_ptr(Y + (int64_t)n * sYn),
        make_shape(Cout, OH, OW),
        make_stride(sYc, sYh, Int<1>{})
    );

    auto mW = make_tensor(
        make_gmem_ptr(W),
        make_shape(Cin, Cout_pg, KH, KW),
        make_stride(sWc, sWoc, sWkh, Int<1>{})
    );

    extern __shared__ unsigned char smem_raw[];
    T* sW_ptr = reinterpret_cast<T*>(smem_raw);
    // sW shape: (OcPerBlock, Cin_pg, KH, KW)
    auto sW = make_tensor(
        make_smem_ptr(sW_ptr),
        make_shape(Int<OcPerBlock>{}, Cin_pg, KH, KW),
        make_stride(Cin_pg * KH * KW, KH * KW, KW, Int<1>{})
    );

    // Load weight tile into shared memory
    int total_w = OcPerBlock * Cin_pg * KH * KW;
    for (int idx = tid; idx < total_w; idx += Threads) {
        int tmp = idx;
        int kw  = tmp % KW;  tmp /= KW;
        int kh  = tmp % KH;  tmp /= KH;
        int icl = tmp % Cin_pg; tmp /= Cin_pg;
        int cc  = tmp;

        int oc = c_base + cc;
        T wval = T(0);
        if (oc < Cout) {
            int g = oc / Cout_pg;
            int oc_local = oc % Cout_pg;
            int ic_full = g * Cin_pg + icl;
            wval = mW(ic_full, oc_local, kh, kw);
        }
        sW(cc, icl, kh, kw) = wval;
    }
    __syncthreads();

    // Precompute output coords for this thread's PVec elements
    int p_idx[PVec];
    int oh_arr[PVec];
    int ow_arr[PVec];

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
        int p = p_block + tid + i * Threads;
        p_idx[i] = p;
        if (p < P_total) {
            oh_arr[i] = p / OW;
            ow_arr[i] = p - oh_arr[i] * OW;
        } else {
            oh_arr[i] = 0;
            ow_arr[i] = 0;
        }
    }

    // Accumulators, initialize with bias
    float acc[OcPerBlock][PVec];
    #pragma unroll
    for (int cc = 0; cc < OcPerBlock; ++cc) {
        int oc = c_base + cc;
        float bval = 0.0f;
        if (B != nullptr && oc < Cout) {
            bval = (float)B[oc];
        }
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
            acc[cc][i] = bval;
        }
    }

    // Determine whether all output channels covered by this block's tile
    // belong to the same group. When true (common case, e.g. Cout_pg % OcPerBlock == 0),
    // the input activation value can be loaded once and reused across all
    // output channels in the tile, avoiding redundant global memory traffic.
    bool same_group = true;
    {
        int g0 = c_base / Cout_pg;
        #pragma unroll
        for (int cc = 1; cc < OcPerBlock; ++cc) {
            int oc_cc = c_base + cc;
            int g_cc = (oc_cc < Cout) ? (oc_cc / Cout_pg) : g0;
            if (g_cc != g0) same_group = false;
        }
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
        int p = p_idx[i];
        if (p >= P_total) continue;
        int oh = oh_arr[i];
        int ow = ow_arr[i];
        for (int kh = 0; kh < KH; ++kh) {
            int th = oh + pad_h - kh * dil_h;
            int rem_h = th % stride_h;
            if (rem_h != 0) continue;
            int ih = th / stride_h;
            if (ih < 0 || ih >= H) continue;
            for (int kw = 0; kw < KW; ++kw) {
                int tw = ow + pad_w - kw * dil_w;
                int rem_w = tw % stride_w;
                if (rem_w != 0) continue;
                int iw = tw / stride_w;
                if (iw < 0 || iw >= Win) continue;
                if (same_group) {
                    int g = c_base / Cout_pg;
                    int ic_base = g * Cin_pg;
                    #pragma unroll
                    for (int icl = 0; icl < Cin_pg; ++icl) {
                        float xval = (float)mX(ic_base + icl, ih, iw);
                        #pragma unroll
                        for (int cc = 0; cc < OcPerBlock; ++cc) {
                            int oc = c_base + cc;
                            if (oc >= Cout) continue;
                            float wval = (float)sW(cc, icl, kh, kw);
                            acc[cc][i] += xval * wval;
                        }
                    }
                } else {
                    #pragma unroll
                    for (int cc = 0; cc < OcPerBlock; ++cc) {
                        int oc = c_base + cc;
                        if (oc >= Cout) continue;
                        int g = oc / Cout_pg;
                        int ic_base = g * Cin_pg;
                        float local_acc = 0.0f;
                        for (int icl = 0; icl < Cin_pg; ++icl) {
                            float xval = (float)mX(ic_base + icl, ih, iw);
                            float wval = (float)sW(cc, icl, kh, kw);
                            local_acc += xval * wval;
                        }
                        acc[cc][i] += local_acc;
                    }
                }
            }
        }
    }

    #pragma unroll
    for (int cc = 0; cc < OcPerBlock; ++cc) {
        int oc = c_base + cc;
        if (oc >= Cout) continue;

        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
            int p = p_idx[i];
            if (p >= P_total) continue;
            int oh = oh_arr[i];
            int ow = ow_arr[i];
            mY(oc, oh, ow) = static_cast<T>(acc[cc][i]);
        }
    }
}

torch::Tensor conv_transpose2d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(w.is_cuda(), "w must be CUDA");
    if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
    if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

    TORCH_CHECK(x.dim() == 4, "x must be [N,Cin,H,W]");
    TORCH_CHECK(w.dim() == 4, "w must be [Cin, Cout/groups, KH, KW]");

    int64_t N   = x.size(0);
    int64_t Cin = x.size(1);
    int64_t H   = x.size(2);
    int64_t Win = x.size(3);

    int64_t Cin_w   = w.size(0);
    int64_t Cout_pg = w.size(1);
    int64_t KH      = w.size(2);
    int64_t KW      = w.size(3);

