    TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be > 0");
    TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be > 0");
    TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be >= 0");
    TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");

    int64_t OH = (H - 1) * stride_h - 2 * pad_h + dil_h * (KH - 1) + 1;
    int64_t OW = (Win - 1) * stride_w - 2 * pad_w + dil_w * (KW - 1) + 1;
    TORCH_CHECK(OH > 0 && OW > 0, "invalid output size computed");

    auto x_c = x.contiguous();
    auto w_c = w.contiguous();

    torch::Tensor b_c;
    const float* b_ptr = nullptr;
