    int64_t P_total = OH * OW;
    int64_t PTile = Threads * PVec;

    dim3 block(Threads);
    dim3 grid(
        (unsigned)((P_total + PTile - 1) / PTile),
        (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
        (unsigned)N
    );

    size_t shmem_bytes = (size_t)OcPerBlock * (size_t)Cin_pg * (size_t)KH * (size_t)KW * sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv_transpose2d_kernel<float><<<grid, block, shmem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)Cin, (int)H, (int)Win,
        (int)Cout, (int)KH, (int)KW,
        stride_h, stride_w,
        pad_h, pad_w,
        dil_h, dil_w,
        groups,
        (int)OH, (int)OW
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv_transpose2d_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
